<?php
require __DIR__.'/_init.php';require __DIR__.'/_layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 try{if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$theme=trim($_POST['theme']??'');$desc=trim($_POST['description']??'');if(!$name)throw new RuntimeException('Informe o nome da categoria.');if($id){$s=db()->prepare('UPDATE categories SET name=?,theme=?,description=? WHERE id=?');$s->execute([$name,$theme,$desc,$id]);}else{$s=db()->prepare('INSERT INTO categories(name,theme,description) VALUES(?,?,?)');$s->execute([$name,$theme,$desc]);}flash('Categoria salva com sucesso.');}
 elseif($action==='delete'){$id=(int)$_POST['id'];$s=db()->prepare('DELETE FROM categories WHERE id=?');$s->execute([$id]);flash('Categoria removida. As fotos vinculadas permanecem sem categoria.');}
 }catch(Throwable $e){flash($e->getMessage(),'error');}header('Location: categories.php');exit;}
$edit=null;if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM categories WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=db()->query('SELECT c.*,COUNT(p.id) photo_count FROM categories c LEFT JOIN photos p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();
admin_header('Categorias e temas','categories');?>
<div class="panel"><h2><?=$edit?'Editar categoria':'Nova categoria'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><div class="form-grid"><label>Nome da categoria<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>Tema<input name="theme" placeholder="Ex.: Família, Amor, Profissões" value="<?=e($edit['theme']??'')?>"></label><label class="wide">Descrição<textarea name="description"><?=e($edit['description']??'')?></textarea></label></div><div class="actions"><button class="btn primary">Salvar categoria</button><?php if($edit):?><a class="btn outline" href="categories.php">Cancelar</a><?php endif;?></div></form></div>
<div class="panel"><h2>Categorias cadastradas</h2><div class="category-admin-grid"><?php foreach($rows as $r):?><article class="category-admin-card"><div class="category-icon">✿</div><div><strong><?=e($r['name'])?></strong><small><?=e($r['theme']?:'Tema não definido')?></small></div><b><?=$r['photo_count']?> fotos</b><a class="btn soft" href="?edit=<?=$r['id']?>">Editar</a></article><?php endforeach;?><?php if(!$rows):?><div class="empty">Nenhuma categoria cadastrada.</div><?php endif;?></div><details class="details-list"><summary>Ver tabela detalhada</summary><div class="table-wrap"><table><thead><tr><th>Categoria</th><th>Tema</th><th>Fotos</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['theme'])?></td><td><?=$r['photo_count']?></td><td><a class="btn soft" href="?edit=<?=$r['id']?>">Editar</a> <form class="inline-form" method="post" onsubmit="return confirm('Excluir esta categoria?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Excluir</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">Nenhuma categoria cadastrada.</td></tr><?php endif;?></tbody></table></div></details></div>
<?php admin_footer();